import React, { useEffect, useState, useRef } from 'react';
import io from 'socket.io-client';

const Chat = () => {
  const [message, setMessage] = useState('');
  const [messages, setMessages] = useState([]);
  const [user, setUser] = useState(null);
  const socket = useRef();

  const token = localStorage.getItem('token');
  const [typingMessage, setTypingMessage] = useState('');
  const [typingUsers, setTypingUsers] = useState([]);
  const messagesEndRef = useRef();

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    };

    useEffect(() => {
    scrollToBottom();
    }, [messages]);

  const handleLogout = () => {
    // setIsLoggedIn(false);
    localStorage.removeItem("token");
    window.location.href = '/login';
  };

  useEffect(() => {
    if (!token) return;

    // Connect to backend
    socket.current = io('http://localhost:4000', {
      auth: {
        token
      }
    });

    // Fetch user info
    fetch('http://localhost:4000/api/auth/me', {
      headers: { 'x-auth-token': token }
    }).then(res => res.json()).then(userData => {
      setUser(userData);
    });

    socket.current.on("updateTypingUsers", (users) => {
        setTypingUsers(users);
    });

    socket.current.on("userTyping", (msg) => {
    setTypingMessage(msg);

    // Clear typing message after 3 seconds
    setTimeout(() => {
      if (typingMessage === msg) {
        setTypingMessage('');
      }
    }, 2000);
    });

    socket.current.on("receiveMessage", (message) => {
    // console.log("📨 Message received:", message);
    setMessages(prev => [...prev, message]);
    });

    socket.current.on('userList', (users) => {
        console.log('Current users online:', users);
    });

    // // Listen for messages
    // socket.current.on('authenticated', () => {
    //     console.log('auth')
    //   socket.current.on('receiveMessage', (msg) => {
    //     setMessages(prev => [...prev, msg]);
    //   });

    //   socket.current.on('userList', (users) => {
    //     console.log('Current users online:', users);
    //   });
    // });

    socket.current.on('unauthorized', () => {
      alert('Authentication failed!');
      window.location.href = '/login';
    });

    return () => {
      socket.current.disconnect();
    };

  }, [token, typingMessage]);

  const sendMessage = (e) => {
    e.preventDefault();
    if (!message.trim()) return;

    const fullMessage = {
      text: message,
      username: user.username,
      time: new Date().toLocaleTimeString()
    };

    socket.current.emit('sendMessage', fullMessage);
    setMessage('');
  };

  return (
    <div>
      <h2>Realtime Chat App with Web Socket</h2>
      <button onClick={handleLogout} style={{ padding: "10px 15px", cursor: "pointer" }}>Logout</button>
      <h3>username: {user?.username}</h3>
        <div style={{
                height: '300px',
                border: '1px solid #ccc',
                overflowY: 'auto',
                padding: '10px'
            }}>
            {messages.map((msg, i) => {
            const isMyMessage = msg.username === user?.username;
                return (
                <div
                    key={i}
                    style={{
                    display: 'flex',
                    justifyContent: isMyMessage ? 'flex-end' : 'flex-start',
                    marginBottom: '10px'
                    }}>
                    <div
                    style={{
                        backgroundColor: isMyMessage ? '#007bff' : '#f1f1f1',
                        color: isMyMessage ? 'white' : 'black',
                        padding: '10px 15px',
                        borderRadius: '10px',
                        maxWidth: '60%',
                        wordWrap: 'break-word'
                    }}>
                    <strong >{msg.username}</strong><br />
                    <span><span style={{paddingRight: '12px'}} >{msg.text}</span><small style={{fontSize: '9px'}} >{msg.time}</small></span>
                    </div>
                </div>
                );
            })}
        <div ref={messagesEndRef}/>
         {typingMessage && (
            <div style={{ fontStyle: 'italic', color: '#666', marginBottom: '5px' }}>
                {typingMessage}
            </div>
        )}
    </div>
    {/* input Label */}
      <form onSubmit={sendMessage}>
        <input
          value={message}
          onChange={(e) => {
            setMessage(e.target.value);
            if (e.target.value.trim() !== '') {
                socket.current.emit('typing', user.username);
            }}
        }
          placeholder="Type a message..."
          style={{ width: '80%' }}
        />
        <button type="submit">Send</button>
      </form>
    </div>
  );
};

export default Chat;
